package io.fireflysoftware.common.config.core.authority;
import io.fireflysoftware.common.config.core.authority.impl.TenantResourceBindingGovernanceServiceImpl;
import io.fireflysoftware.common.config.interfaces.authority.TenantResourceBindingContracts.*;
import org.junit.jupiter.api.Test;
import org.springframework.r2dbc.connection.R2dbcTransactionManager;
import reactor.core.publisher.Mono;
import java.util.UUID;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class TenantResourceBindingGovernanceTest {
 @Test void preparationUsesExplicitBindingPolicyScopeAndOriginalBudget(){var f=new TenantResourceBindingServiceTest.Fixture();var provider=mock(TenantResourceBindingNativeGovernance.class);when(provider.connectionFactory()).thenReturn(f.factory);var source=new Preparation(UUID.randomUUID(),TenantResourceBindingServiceTest.command(Operation.TENANT_RESOURCE_BINDING_ESTABLISH,0),InstitutionAuthorityBudgetTest.NOW.plusSeconds(60).toEpochMilli());var budget=f.budget();when(provider.prepare(any(),eq(source))).thenAnswer(call->{InstitutionAuthorityAuthorization.Admission admission=call.getArgument(0);assertSame(budget,admission.originalBudget());assertEquals(InstitutionAuthorityAuthorization.Operation.TENANT_RESOURCE_BINDING_PREPARE,admission.scope().operation());assertEquals(InstitutionAuthorityAuthorization.ResourceType.TENANT_RESOURCE_BINDING_PROPOSAL,admission.scope().resourceType());return f.owned().thenReturn(new GovernanceReceipt(source.actionId(),TenantResourceBindingCodec.preparationDigest(source),new Proposal(source.target().proposalId(),TenantResourceBindingCodec.commandDigest(source.target()),"DRAFT",0,source.notAfterEpochMillis()),InstitutionAuthorityBudgetTest.NOW.plusMillis(500).toEpochMilli(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID()));});var service=new TenantResourceBindingGovernanceServiceImpl(f.governance,new R2dbcTransactionManager(f.factory),provider);assertEquals("DRAFT",service.prepare(source,budget).block().proposal().state());assertEquals(1,f.begins.get());assertEquals(1,f.commits.get());}
 @Test void missingNativePreparationNeverBecomesSuccessfulProposal(){var f=new TenantResourceBindingServiceTest.Fixture();var provider=mock(TenantResourceBindingNativeGovernance.class);when(provider.connectionFactory()).thenReturn(f.factory);when(provider.prepare(any(),any())).thenReturn(Mono.empty());var service=new TenantResourceBindingGovernanceServiceImpl(f.governance,new R2dbcTransactionManager(f.factory),provider);var source=new Preparation(UUID.randomUUID(),TenantResourceBindingServiceTest.command(Operation.TENANT_RESOURCE_BINDING_ESTABLISH,0),InstitutionAuthorityBudgetTest.NOW.plusSeconds(60).toEpochMilli());assertThrows(Exception.class,()->service.prepare(source,f.budget()).block());assertEquals(0,f.commits.get());assertEquals(1,f.rollbacks.get());}
 @Test void proposalTargetAndOriginalDeadlineParticipateInCanonicalIdentity(){var c=TenantResourceBindingServiceTest.command(Operation.TENANT_RESOURCE_BINDING_ESTABLISH,0);var a=new Preparation(UUID.randomUUID(),c,InstitutionAuthorityBudgetTest.NOW.plusSeconds(60).toEpochMilli());var b=new Preparation(a.actionId(),c,a.notAfterEpochMillis()+1);assertNotEquals(TenantResourceBindingCodec.preparationDigest(a),TenantResourceBindingCodec.preparationDigest(b));var approve=new DecisionCommand(UUID.randomUUID(),c.definition().resourceTenant(),c.proposalId(),DecisionOperation.APPROVE,1,TenantResourceBindingCodec.commandDigest(c),a.notAfterEpochMillis());var reject=new DecisionCommand(approve.actionId(),approve.resourceTenant(),approve.proposalId(),DecisionOperation.REJECT,approve.expectedControlVersion(),approve.targetDigest(),approve.notAfterEpochMillis());assertNotEquals(TenantResourceBindingCodec.decisionDigest(approve),TenantResourceBindingCodec.decisionDigest(reject));}
 @Test void mismatchedNativeReceiptRefusesBeforeCommit(){var f=new TenantResourceBindingServiceTest.Fixture();var provider=mock(TenantResourceBindingNativeGovernance.class);when(provider.connectionFactory()).thenReturn(f.factory);var source=new Preparation(UUID.randomUUID(),TenantResourceBindingServiceTest.command(Operation.TENANT_RESOURCE_BINDING_ESTABLISH,0),InstitutionAuthorityBudgetTest.NOW.plusSeconds(60).toEpochMilli());when(provider.prepare(any(),any())).thenReturn(Mono.just(new GovernanceReceipt(UUID.randomUUID(),TenantResourceBindingCodec.preparationDigest(source),new Proposal(source.target().proposalId(),TenantResourceBindingCodec.commandDigest(source.target()),"DRAFT",0,source.notAfterEpochMillis()),InstitutionAuthorityBudgetTest.NOW.plusMillis(500).toEpochMilli(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID())));var service=new TenantResourceBindingGovernanceServiceImpl(f.governance,new R2dbcTransactionManager(f.factory),provider);assertThrows(Exception.class,()->service.prepare(source,f.budget()).block());assertEquals(0,f.commits.get());assertEquals(1,f.rollbacks.get());}

}
